  // --- States ---
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const touchStartTimeRef = useRef<number>(0);
  const [slideDirection, setSlideDirection] = useState<'up' | 'down' | null>(null);
  const lastScrollTime = useRef<number>(0);

  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    const y = e.targetTouches[0]?.clientY ?? e.touches[0]?.clientY ?? 0;
    setTouchStart(y);
    touchStartTimeRef.current = Date.now();
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.targetTouches[0]) {
      setTouchEnd(e.targetTouches[0].clientY);
    }
  };
  const [videosList, setVideosList] = useState<CastingLiveVideo[]>(() => {
    const cached = localStorage.getItem('coll_casting_live_videos');
    const parseCategory = (cat?: string): any => {
      if (!cat) return 'Fashion';
      const map: Record<string, string> = {
        todos: 'Todos',
        fashion: 'Fashion',
        finanzas: 'Finanzas',
        models: 'Modelos',
        modelos: 'Modelos',
        backstage: 'BackStage',
        investors: 'Investors',
        tiendas: 'Tiendas',
        catwalk: 'Catwalk'
      };
      return map[cat.toLowerCase()] || cat;
    };
    
    const initialVideosMapped = initialVideos.map(v => ({
      ...v,
      videoCategory: parseCategory(v.videoCategory)
    }));

    if (cached) {
      try {
        const parsed = JSON.parse(cached) as CastingLiveVideo[];
        if (Array.isArray(parsed) && parsed.length > 0) {
          const parsedMapped = parsed.map(v => ({
            ...v,
            videoCategory: parseCategory(v.videoCategory)
          }));
          
          // Merge keeping cached ones (uploaded ones) at the top, appending initial ones
          const merged = [...parsedMapped];
          for (const initVid of initialVideosMapped) {
            if (!merged.some(m => m.id === initVid.id)) {
              merged.push(initVid);
            }
          }
          const dedupeList = (list: CastingLiveVideo[]) => {
            const result: CastingLiveVideo[] = [];
            const seenIds = new Set<string>();
            const seenKeys = new Set<string>();
            for (const item of list) {
              if (!item || !item.id) continue;
              const key = item.videoUrl ? `${item.videoUrl}_${item.description || ''}` : item.id;
              if (!seenIds.has(item.id) && !seenKeys.has(key)) {
                result.push(item);
                seenIds.add(item.id);
                seenKeys.add(key);
              }
            }
            return result;
          };
          return dedupeList(merged);
        }
      } catch (e) {
        // fallback
      }
    }
    return initialVideosMapped;
  });

  const syncVideosFromStorage = () => {
    const cached = localStorage.getItem('coll_casting_live_videos');
    const parseCategory = (cat?: string): any => {
      if (!cat) return 'Fashion';
      const map: Record<string, string> = {
        todos: 'Todos',
        fashion: 'Fashion',
        finanzas: 'Finanzas',
        models: 'Modelos',
        modelos: 'Modelos',
        backstage: 'BackStage',
        investors: 'Investors',
        tiendas: 'Tiendas',
        catwalk: 'Catwalk'
      };
      return map[cat.toLowerCase()] || cat;
    };
    
    const initialVideosMapped = initialVideos.map(v => ({
      ...v,
      videoCategory: parseCategory(v.videoCategory)
    }));

    if (cached) {
      try {
        const parsed = JSON.parse(cached) as CastingLiveVideo[];
        if (Array.isArray(parsed) && parsed.length > 0) {
          const parsedMapped = parsed.map(v => ({
            ...v,
            videoCategory: parseCategory(v.videoCategory)
          }));
          
          const merged = [...parsedMapped];
          for (const initVid of initialVideosMapped) {
            if (!merged.some(m => m.id === initVid.id)) {
              merged.push(initVid);
            }
          }
          const dedupeList = (list: CastingLiveVideo[]) => {
            const result: CastingLiveVideo[] = [];
            const seenIds = new Set<string>();
            const seenKeys = new Set<string>();
            for (const item of list) {
              if (!item || !item.id) continue;
              const key = item.videoUrl ? `${item.videoUrl}_${item.description || ''}` : item.id;
              if (!seenIds.has(item.id) && !seenKeys.has(key)) {
                result.push(item);
                seenIds.add(item.id);
                seenKeys.add(key);
              }
            }
            return result;
          };
          setVideosList(dedupeList(merged));
          return;
        }
      } catch (e) {
        console.error(e);
      }
    }
    setVideosList(initialVideosMapped);
  };

