  // Simulation: Connect remaining offline participants sequentially if user paid for Finanzas session AND scenario is not 'not_present'
  useEffect(() => {
    if (selectedCategoryFilter !== 'Finanzas') return;
    if (finanzasScenario === 'not_present') return; // Stop sequential auto-connect if simulating Scenario A
    const hasPaid = localStorage.getItem('user_paid_finanzas_session') === 'true';
    if (!hasPaid) return;

    const offlineUsers = FINANZAS_USERS.filter(u => !joinedPresenterIds.includes(u.id));
    if (offlineUsers.length > 0) {
      const timer = setTimeout(() => {
        const nextToConnect = offlineUsers[0];
        setJoinedPresenterIds(prev => {
          if (prev.includes(nextToConnect.id)) return prev;
          const nextList = [...prev, nextToConnect.id];
          return nextList;
        });

        // Also add them to the queue as "waiting" if they are not already in it
        setFinanzasPresentationQueue(prev => {
          if (prev.some(item => item.id === nextToConnect.id)) return prev;
          const now = new Date();
          const formattedTime = now.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
          return [...prev, {
            id: nextToConnect.id,
            name: nextToConnect.name,
            avatar: nextToConnect.avatar,
            role: nextToConnect.role,
            requestTime: formattedTime,
            status: 'waiting' as const
          }];
        });
      }, 1000); // login sequence every second
      return () => clearTimeout(timer);
    }
  }, [selectedCategoryFilter, joinedPresenterIds, finanzasScenario]);

