  const handleAddToCart = (product: any, storeName: string) => {
    const itemUniqueId = `${product.id || 'p'}-${product.selectedColorChoice || 'Default'}-${product.selectedSizeChoice || 'M'}-${product.isCustomFit ? 'custom' : 'standard'}`;
    
    // Also add to investorPurchases so it appears in "MIS ADQUISICIONES" window (captura z.png)
    setInvestorPurchases(prev => {
      const alreadyPurchased = prev.some(p => p.productName === product.name && p.storeName === storeName);
      if (alreadyPurchased) {
        return prev;
      }
      const newPurchase = {
        id: `purchase-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
        productName: product.name,
        price: product.price,
        image: product.image,
        storeName: storeName,
        date: 'Añadido'
      };
      return [newPurchase, ...prev];
    });

    setCartItems(prev => {
      const existingIdx = prev.findIndex(item => item.id === itemUniqueId);
      if (existingIdx !== -1) {
        const updated = [...prev];
        updated[existingIdx] = {
          ...updated[existingIdx],
          quantity: updated[existingIdx].quantity + 1
        };
        alert(`🛒 ¡Producto añadido al carrito y a tus adquisiciones!\n\nSe ha incrementado la cantidad de "${product.name}" en tu carrito.`);
        return updated;
      } else {
        alert(`🛒 ¡Producto añadido al carrito y a tus adquisiciones!\n\nHas añadido "${product.name}" (Talla: ${product.selectedSizeChoice || 'M'}, Color: ${product.selectedColorChoice || 'Por defecto'}) al carrito.`);
        return [...prev, {
          id: itemUniqueId,
          product,
          quantity: 1,
          selectedColor: product.selectedColorChoice || 'Por defecto',
          selectedSize: product.selectedSizeChoice || 'M',
          isCustomFit: product.isCustomFit || false,
          customBust: product.customBust || 90,
          customWaist: product.customWaist || 70,
          customHips: product.customHips || 95,
          customHeight: product.customHeight || 170,
          storeName
        }];
      }
    });
  };

