  // Built-in list of beautiful loop videos to choose during upload
  const PRESET_VIDEOS = [
    { label: 'NUCLEO.MP4', url: 'https://assets.mixkit.co/videos/preview/mixkit-beautiful-woman-posing-with-a-red-light-40486-large.mp4' }
  ];

  const videoRefs = useRef<(HTMLVideoElement | null)[]>([]);
