    try {
      localStorage.setItem('coll_casting_live_videos', JSON.stringify(nextVideos));
    } catch (e) {
      console.error(e);
    }
    
    // Also remove from saved_videos of all profiles in localStorage to ensure full sync on profiles
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('saved_videos_')) {
          const savedStr = localStorage.getItem(key);
          if (savedStr) {
            try {
              const parsed = JSON.parse(savedStr);
              if (Array.isArray(parsed)) {
                const updatedSaved = parsed.filter((v: any) => v.id !== videoId);
                localStorage.setItem(key, JSON.stringify(updatedSaved));
              }
            } catch (err) {
              console.error(`Error parsing key ${key}:`, err);
            }
          }
        }
      }
    } catch (e) {
      console.error('Error removing from saved_videos list during modal delete', e);
    }

    try {
      window.dispatchEvent(new Event('saved_videos_updated'));
      window.dispatchEvent(new Event('storage'));
    } catch (err) {
      console.error(err);
    }
