                                <div className="relative w-7 h-7 rounded-lg overflow-hidden bg-slate-200 flex-shrink-0">
                                  <img src={song.cover} alt={song.title} className="w-full h-full object-cover" referrerPolicy="no-referrer" />
                                  <button
                                    type="button"
                                    onClick={() => setSoundPlayingPreviewId(isPlaying ? null : song.id)}
                                    className="absolute inset-0 bg-black/30 flex items-center justify-center text-white cursor-pointer border-0"
                                  >
                                    {isPlaying ? (
                                      <div className="flex items-end gap-0.5 h-2">
                                        <div className="w-0.5 bg-[#fe2c55] h-2 animate-[bounce_0.8s_infinite]" style={{ animationDelay: '0.1s' }} />
                                        <div className="w-0.5 bg-[#fe2c55] h-1.5 animate-[bounce_0.8s_infinite]" style={{ animationDelay: '0.3s' }} />
                                        <div className="w-0.5 bg-[#fe2c55] h-2.5 animate-[bounce_0.8s_infinite]" style={{ animationDelay: '0.5s' }} />
                                      </div>
                                    ) : (
                                      <Play className="w-2.5 h-2.5 fill-white text-white" />
                                    )}
                                  </button>
                                </div>
