                      const name = lead.itemName ? lead.itemName.toLowerCase().trim() : '';
                      const target = selectedDirectServiceFilter.toLowerCase().trim();
                      if (target === 'apariciones en los resultados finales') {
                        return name.includes('resultados') || name.includes('apariciones en los resultados');
                      }
                      if (target === 'agendar una cita') {
                        return name.includes('cita') || name.includes('agendar') || name.includes('agende');
                      }
                      if (target === 'tienda de atelier' || target === 'otras ofertas') {
                        return name.includes('tienda') || name.includes('atelier') || name.includes('boutique') || name.includes('otras') || name.includes('otro');
                      }
                      return name === target;
