                          (activeVideo.username && userProfile.username && activeVideo.username.toLowerCase().trim() === userProfile.username.toLowerCase().trim()) ||
                          (activeVideo.name && userProfile.name && activeVideo.name.toLowerCase().trim() === userProfile.name.toLowerCase().trim())
