                { id: 2, user: 'Miranda Kerr', action: 'ha enviado tus sugerencias de inversión a un referido.', time: 'Hace 23 min', avatar: 'https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&q=80&w=100', isUnread: true },
                { id: 3, user: 'Fashions Finance', action: 'aprobó el proyecto de fondo de cobertura "BackstageBcn".', time: 'Hace 1 hora', avatar: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&q=80&w=100', isUnread: false },
                { id: 4, user: 'Candice Swanepoel', action: 'inició un nuevo LIVE interactivo. ¡Conéctate para apoyarla!', time: 'Hace 2 horas', avatar: 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&q=80&w=150', isUnread: false }
