                <div className="bg-white p-1.5 rounded-lg border border-indigo-100/60 shadow-xs">
                  <span className="text-[10px] text-slate-400 block font-medium">Visitas hoy</span>
                  <span className="text-xs font-black text-indigo-700 font-mono">1,482</span>
                </div>
